with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'التحقق من التنبؤات الجوية والمهارة الاحتمالية','مقاييس التحقق الحتمي والاحتمالي والمكاني، تقييم المجموعات التنبؤية والظواهر النادرة، وربط المهارة بالقيمة التشغيلية.',64,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'مقاييس التحقق الحتمي والأحداث',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التحقق الاحتمالي والمكاني والقيمة التشغيلية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('forecast-verification-framework','إطار التحقق من التنبؤات الجوية','المشاهدة والمرجع ومطابقة التوقع','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يحدد التحقق مدى توافق التنبؤ مع مرجع رصدي مناسب، ويتطلب تعريف المتغير والفترة والمجال ومهلة التنبؤ ومصدر الحقيقة المرجعية. لا يوجد مقياس واحد يلائم جميع الأغراض."},{"type":"heading","text":"الإطار الإحصائي"},{"type":"text","text":"يتطلب التحقق تحديد وحدة التحليل والعينة والمرجع ومهلة التنبؤ والعتبة عند الحاجة. تختلف المقاييس في حساسيتها للأحداث النادرة والقيم المتطرفة والانحياز، لذلك ينبغي تفسير مجموعة مؤشرات بدلاً من ترتيب النماذج بمقياس منفرد."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["توقعات مؤرشفة مع وقت الإصدار ومهلة التنبؤ.","مشاهدات مرجعية مع بيانات الجودة والموقع والتوقيت.","تعريف واضح للحدث والعتبات والوحدات.","تقسيم زمني ومكاني للعينة وفصل التطوير عن التقييم.","سجل بالبيانات المستبعدة وأسباب الاستبعاد."]},{"type":"heading","text":"خطوات التقييم"},{"type":"list","items":["حدد غرض التحقق والمستخدم ونوع التنبؤ.","افحص مواءمة التوقيت والموقع والوحدات.","اختر المقاييس التي تجيب عن سؤال التقييم.","احسب المؤشرات على عينات مناسبة وقارن الفئات.","حلل الحساسية واللايقين وقدم النتائج مع سياقها."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"إطار التحقق من التنبؤات الجوية","text":"ضع بروتوكول تحقق يحدد المتغير والمرجع والفترة ومهلة التنبؤ. استخدم مجموعة صغيرة افتراضية للتوضيح، ولا تعمم نتيجة عينة محدودة على الأداء المناخي الكامل."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع بروتوكول تحقق يحدد المتغير والمرجع والفترة ومهلة التنبؤ."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اختيار مقياس لا يلائم طبيعة الحدث أو توزيع العينة.","تسرب بيانات فترة التقييم إلى المعايرة أو التطوير.","إهمال جودة المرجع أو اختلاف التمثيل المكاني.","تفسير المؤشر دون معدل حدوث الظاهرة وحجم العينة.","اعتبار الارتباط أو التمييز دليلاً كافياً على المعايرة."]},{"type":"callout","text":"التحقق الجيد يربط المقياس بسؤال القرار، ويعرض خصائص العينة وعدم اليقين وحدود المقارنة بوضوح."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يحول التحقق أرشيف التوقعات والمشاهدات إلى دليل قابل للمقارنة والتحسين. وتحتاج الممارسة المهنية إلى مقاييس متعددة ومرجع موثوق وفصل مستقل بين التطوير والتقييم."}]}'::jsonb,8960,55,'["شرح مبدأ مقياس التحقق أو إطار التقييم","اختيار البيانات والعينة والمرجع المناسب","تفسير نتائج المهارة واللايقين لأغراض التحسين التشغيلي"]'::jsonb,'مقاييس التحقق الحتمي والأحداث'),
('forecast-bias-and-error','الانحياز والخطأ في التنبؤ','الخطأ المتوسط والمطلق والجذري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس الانحياز الميل المنهجي إلى الزيادة أو النقص، بينما تقيس MAE وRMSE أحجام الأخطاء بطرق مختلفة. تتأثر المقاييس بالقيم المتطرفة وبالتوزيع الإحصائي للعينة."},{"type":"heading","text":"الإطار الإحصائي"},{"type":"text","text":"يتطلب التحقق تحديد وحدة التحليل والعينة والمرجع ومهلة التنبؤ والعتبة عند الحاجة. تختلف المقاييس في حساسيتها للأحداث النادرة والقيم المتطرفة والانحياز، لذلك ينبغي تفسير مجموعة مؤشرات بدلاً من ترتيب النماذج بمقياس منفرد."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["توقعات مؤرشفة مع وقت الإصدار ومهلة التنبؤ.","مشاهدات مرجعية مع بيانات الجودة والموقع والتوقيت.","تعريف واضح للحدث والعتبات والوحدات.","تقسيم زمني ومكاني للعينة وفصل التطوير عن التقييم.","سجل بالبيانات المستبعدة وأسباب الاستبعاد."]},{"type":"heading","text":"خطوات التقييم"},{"type":"list","items":["حدد غرض التحقق والمستخدم ونوع التنبؤ.","افحص مواءمة التوقيت والموقع والوحدات.","اختر المقاييس التي تجيب عن سؤال التقييم.","احسب المؤشرات على عينات مناسبة وقارن الفئات.","حلل الحساسية واللايقين وقدم النتائج مع سياقها."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الانحياز والخطأ في التنبؤ","text":"قارن دلالة الانحياز وMAE وRMSE على مجموعة توقعات افتراضية. استخدم مجموعة صغيرة افتراضية للتوضيح، ولا تعمم نتيجة عينة محدودة على الأداء المناخي الكامل."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن دلالة الانحياز وMAE وRMSE على مجموعة توقعات افتراضية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اختيار مقياس لا يلائم طبيعة الحدث أو توزيع العينة.","تسرب بيانات فترة التقييم إلى المعايرة أو التطوير.","إهمال جودة المرجع أو اختلاف التمثيل المكاني.","تفسير المؤشر دون معدل حدوث الظاهرة وحجم العينة.","اعتبار الارتباط أو التمييز دليلاً كافياً على المعايرة."]},{"type":"callout","text":"التحقق الجيد يربط المقياس بسؤال القرار، ويعرض خصائص العينة وعدم اليقين وحدود المقارنة بوضوح."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يحول التحقق أرشيف التوقعات والمشاهدات إلى دليل قابل للمقارنة والتحسين. وتحتاج الممارسة المهنية إلى مقاييس متعددة ومرجع موثوق وفصل مستقل بين التطوير والتقييم."}]}'::jsonb,8970,55,'["شرح مبدأ مقياس التحقق أو إطار التقييم","اختيار البيانات والعينة والمرجع المناسب","تفسير نتائج المهارة واللايقين لأغراض التحسين التشغيلي"]'::jsonb,'مقاييس التحقق الحتمي والأحداث'),
('contingency-table-weather','جدول الطوارئ للظواهر الجوية','الإصابات والإخفاقات والإنذارات الكاذبة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينظم جدول الطوارئ نتائج توقع حدث ثنائي إلى إصابات صحيحة وإخفاقات وإنذارات كاذبة ورفض صحيح. تشتق منه مؤشرات مثل POD وFAR وCSI وفق تعريف الحدث والعتبة."},{"type":"heading","text":"الإطار الإحصائي"},{"type":"text","text":"يتطلب التحقق تحديد وحدة التحليل والعينة والمرجع ومهلة التنبؤ والعتبة عند الحاجة. تختلف المقاييس في حساسيتها للأحداث النادرة والقيم المتطرفة والانحياز، لذلك ينبغي تفسير مجموعة مؤشرات بدلاً من ترتيب النماذج بمقياس منفرد."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["توقعات مؤرشفة مع وقت الإصدار ومهلة التنبؤ.","مشاهدات مرجعية مع بيانات الجودة والموقع والتوقيت.","تعريف واضح للحدث والعتبات والوحدات.","تقسيم زمني ومكاني للعينة وفصل التطوير عن التقييم.","سجل بالبيانات المستبعدة وأسباب الاستبعاد."]},{"type":"heading","text":"خطوات التقييم"},{"type":"list","items":["حدد غرض التحقق والمستخدم ونوع التنبؤ.","افحص مواءمة التوقيت والموقع والوحدات.","اختر المقاييس التي تجيب عن سؤال التقييم.","احسب المؤشرات على عينات مناسبة وقارن الفئات.","حلل الحساسية واللايقين وقدم النتائج مع سياقها."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"جدول الطوارئ للظواهر الجوية","text":"أنشئ جدول طوارئ افتراضياً واحسب مؤشرين منه. استخدم مجموعة صغيرة افتراضية للتوضيح، ولا تعمم نتيجة عينة محدودة على الأداء المناخي الكامل."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ جدول طوارئ افتراضياً واحسب مؤشرين منه."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اختيار مقياس لا يلائم طبيعة الحدث أو توزيع العينة.","تسرب بيانات فترة التقييم إلى المعايرة أو التطوير.","إهمال جودة المرجع أو اختلاف التمثيل المكاني.","تفسير المؤشر دون معدل حدوث الظاهرة وحجم العينة.","اعتبار الارتباط أو التمييز دليلاً كافياً على المعايرة."]},{"type":"callout","text":"التحقق الجيد يربط المقياس بسؤال القرار، ويعرض خصائص العينة وعدم اليقين وحدود المقارنة بوضوح."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يحول التحقق أرشيف التوقعات والمشاهدات إلى دليل قابل للمقارنة والتحسين. وتحتاج الممارسة المهنية إلى مقاييس متعددة ومرجع موثوق وفصل مستقل بين التطوير والتقييم."}]}'::jsonb,8980,55,'["شرح مبدأ مقياس التحقق أو إطار التقييم","اختيار البيانات والعينة والمرجع المناسب","تفسير نتائج المهارة واللايقين لأغراض التحسين التشغيلي"]'::jsonb,'مقاييس التحقق الحتمي والأحداث'),
('probability-of-detection','احتمال الكشف عن الظاهرة','الحساسية وتغطية الأحداث المرصودة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس POD نسبة الأحداث المرصودة التي سبقها توقع إيجابي. لا يصف وحده جودة النظام لأن رفع التوقعات قد يزيد الكشف ويزيد الإنذارات الكاذبة."},{"type":"heading","text":"الإطار الإحصائي"},{"type":"text","text":"يتطلب التحقق تحديد وحدة التحليل والعينة والمرجع ومهلة التنبؤ والعتبة عند الحاجة. تختلف المقاييس في حساسيتها للأحداث النادرة والقيم المتطرفة والانحياز، لذلك ينبغي تفسير مجموعة مؤشرات بدلاً من ترتيب النماذج بمقياس منفرد."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["توقعات مؤرشفة مع وقت الإصدار ومهلة التنبؤ.","مشاهدات مرجعية مع بيانات الجودة والموقع والتوقيت.","تعريف واضح للحدث والعتبات والوحدات.","تقسيم زمني ومكاني للعينة وفصل التطوير عن التقييم.","سجل بالبيانات المستبعدة وأسباب الاستبعاد."]},{"type":"heading","text":"خطوات التقييم"},{"type":"list","items":["حدد غرض التحقق والمستخدم ونوع التنبؤ.","افحص مواءمة التوقيت والموقع والوحدات.","اختر المقاييس التي تجيب عن سؤال التقييم.","احسب المؤشرات على عينات مناسبة وقارن الفئات.","حلل الحساسية واللايقين وقدم النتائج مع سياقها."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"احتمال الكشف عن الظاهرة","text":"اشرح لماذا يجب قراءة POD مع مؤشر للإنذارات الكاذبة. استخدم مجموعة صغيرة افتراضية للتوضيح، ولا تعمم نتيجة عينة محدودة على الأداء المناخي الكامل."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا يجب قراءة POD مع مؤشر للإنذارات الكاذبة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اختيار مقياس لا يلائم طبيعة الحدث أو توزيع العينة.","تسرب بيانات فترة التقييم إلى المعايرة أو التطوير.","إهمال جودة المرجع أو اختلاف التمثيل المكاني.","تفسير المؤشر دون معدل حدوث الظاهرة وحجم العينة.","اعتبار الارتباط أو التمييز دليلاً كافياً على المعايرة."]},{"type":"callout","text":"التحقق الجيد يربط المقياس بسؤال القرار، ويعرض خصائص العينة وعدم اليقين وحدود المقارنة بوضوح."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يحول التحقق أرشيف التوقعات والمشاهدات إلى دليل قابل للمقارنة والتحسين. وتحتاج الممارسة المهنية إلى مقاييس متعددة ومرجع موثوق وفصل مستقل بين التطوير والتقييم."}]}'::jsonb,8990,55,'["شرح مبدأ مقياس التحقق أو إطار التقييم","اختيار البيانات والعينة والمرجع المناسب","تفسير نتائج المهارة واللايقين لأغراض التحسين التشغيلي"]'::jsonb,'مقاييس التحقق الحتمي والأحداث'),
('false-alarm-ratio','نسبة الإنذار الكاذب','موثوقية التنبيه الإيجابي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تقيس FAR نسبة التوقعات الإيجابية التي لم تتحقق وفق تعريف الحدث. تعتمد على العتبة وتواتر الحدث وجودة الرصد، وقد تختلف بين المناطق والفصول."},{"type":"heading","text":"الإطار الإحصائي"},{"type":"text","text":"يتطلب التحقق تحديد وحدة التحليل والعينة والمرجع ومهلة التنبؤ والعتبة عند الحاجة. تختلف المقاييس في حساسيتها للأحداث النادرة والقيم المتطرفة والانحياز، لذلك ينبغي تفسير مجموعة مؤشرات بدلاً من ترتيب النماذج بمقياس منفرد."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["توقعات مؤرشفة مع وقت الإصدار ومهلة التنبؤ.","مشاهدات مرجعية مع بيانات الجودة والموقع والتوقيت.","تعريف واضح للحدث والعتبات والوحدات.","تقسيم زمني ومكاني للعينة وفصل التطوير عن التقييم.","سجل بالبيانات المستبعدة وأسباب الاستبعاد."]},{"type":"heading","text":"خطوات التقييم"},{"type":"list","items":["حدد غرض التحقق والمستخدم ونوع التنبؤ.","افحص مواءمة التوقيت والموقع والوحدات.","اختر المقاييس التي تجيب عن سؤال التقييم.","احسب المؤشرات على عينات مناسبة وقارن الفئات.","حلل الحساسية واللايقين وقدم النتائج مع سياقها."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"نسبة الإنذار الكاذب","text":"قارن نظامين لهما POD متقارب وFAR مختلف. استخدم مجموعة صغيرة افتراضية للتوضيح، ولا تعمم نتيجة عينة محدودة على الأداء المناخي الكامل."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن نظامين لهما POD متقارب وFAR مختلف."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اختيار مقياس لا يلائم طبيعة الحدث أو توزيع العينة.","تسرب بيانات فترة التقييم إلى المعايرة أو التطوير.","إهمال جودة المرجع أو اختلاف التمثيل المكاني.","تفسير المؤشر دون معدل حدوث الظاهرة وحجم العينة.","اعتبار الارتباط أو التمييز دليلاً كافياً على المعايرة."]},{"type":"callout","text":"التحقق الجيد يربط المقياس بسؤال القرار، ويعرض خصائص العينة وعدم اليقين وحدود المقارنة بوضوح."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يحول التحقق أرشيف التوقعات والمشاهدات إلى دليل قابل للمقارنة والتحسين. وتحتاج الممارسة المهنية إلى مقاييس متعددة ومرجع موثوق وفصل مستقل بين التطوير والتقييم."}]}'::jsonb,9000,55,'["شرح مبدأ مقياس التحقق أو إطار التقييم","اختيار البيانات والعينة والمرجع المناسب","تفسير نتائج المهارة واللايقين لأغراض التحسين التشغيلي"]'::jsonb,'مقاييس التحقق الحتمي والأحداث'),
('critical-success-index','مؤشر النجاح الحرج','التوازن بين الكشف والإنذار الكاذب','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يجمع CSI بين الإصابات الصحيحة والإخفاقات والإنذارات الكاذبة، ويستخدم لتقييم توقع الأحداث النادرة نسبياً. لكنه لا يتضمن الرفض الصحيح ويتأثر بمعدل حدوث الظاهرة."},{"type":"heading","text":"الإطار الإحصائي"},{"type":"text","text":"يتطلب التحقق تحديد وحدة التحليل والعينة والمرجع ومهلة التنبؤ والعتبة عند الحاجة. تختلف المقاييس في حساسيتها للأحداث النادرة والقيم المتطرفة والانحياز، لذلك ينبغي تفسير مجموعة مؤشرات بدلاً من ترتيب النماذج بمقياس منفرد."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["توقعات مؤرشفة مع وقت الإصدار ومهلة التنبؤ.","مشاهدات مرجعية مع بيانات الجودة والموقع والتوقيت.","تعريف واضح للحدث والعتبات والوحدات.","تقسيم زمني ومكاني للعينة وفصل التطوير عن التقييم.","سجل بالبيانات المستبعدة وأسباب الاستبعاد."]},{"type":"heading","text":"خطوات التقييم"},{"type":"list","items":["حدد غرض التحقق والمستخدم ونوع التنبؤ.","افحص مواءمة التوقيت والموقع والوحدات.","اختر المقاييس التي تجيب عن سؤال التقييم.","احسب المؤشرات على عينات مناسبة وقارن الفئات.","حلل الحساسية واللايقين وقدم النتائج مع سياقها."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"مؤشر النجاح الحرج","text":"فسر ما الذي يخسره التقييم عند الاعتماد على CSI وحده. استخدم مجموعة صغيرة افتراضية للتوضيح، ولا تعمم نتيجة عينة محدودة على الأداء المناخي الكامل."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر ما الذي يخسره التقييم عند الاعتماد على CSI وحده."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اختيار مقياس لا يلائم طبيعة الحدث أو توزيع العينة.","تسرب بيانات فترة التقييم إلى المعايرة أو التطوير.","إهمال جودة المرجع أو اختلاف التمثيل المكاني.","تفسير المؤشر دون معدل حدوث الظاهرة وحجم العينة.","اعتبار الارتباط أو التمييز دليلاً كافياً على المعايرة."]},{"type":"callout","text":"التحقق الجيد يربط المقياس بسؤال القرار، ويعرض خصائص العينة وعدم اليقين وحدود المقارنة بوضوح."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يحول التحقق أرشيف التوقعات والمشاهدات إلى دليل قابل للمقارنة والتحسين. وتحتاج الممارسة المهنية إلى مقاييس متعددة ومرجع موثوق وفصل مستقل بين التطوير والتقييم."}]}'::jsonb,9010,55,'["شرح مبدأ مقياس التحقق أو إطار التقييم","اختيار البيانات والعينة والمرجع المناسب","تفسير نتائج المهارة واللايقين لأغراض التحسين التشغيلي"]'::jsonb,'مقاييس التحقق الحتمي والأحداث'),
('reliability-diagrams','مخططات موثوقية التنبؤ الاحتمالي','مطابقة الاحتمال المعلن للتواتر المرصود','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقارن مخطط الموثوقية الاحتمالات المتوقعة بالتواتر الفعلي للحدث ضمن فئات احتمالية. يتطلب عدداً كافياً من الحالات في كل فئة وفحص عدم اليقين الإحصائي."},{"type":"heading","text":"الإطار الإحصائي"},{"type":"text","text":"يتطلب التحقق تحديد وحدة التحليل والعينة والمرجع ومهلة التنبؤ والعتبة عند الحاجة. تختلف المقاييس في حساسيتها للأحداث النادرة والقيم المتطرفة والانحياز، لذلك ينبغي تفسير مجموعة مؤشرات بدلاً من ترتيب النماذج بمقياس منفرد."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["توقعات مؤرشفة مع وقت الإصدار ومهلة التنبؤ.","مشاهدات مرجعية مع بيانات الجودة والموقع والتوقيت.","تعريف واضح للحدث والعتبات والوحدات.","تقسيم زمني ومكاني للعينة وفصل التطوير عن التقييم.","سجل بالبيانات المستبعدة وأسباب الاستبعاد."]},{"type":"heading","text":"خطوات التقييم"},{"type":"list","items":["حدد غرض التحقق والمستخدم ونوع التنبؤ.","افحص مواءمة التوقيت والموقع والوحدات.","اختر المقاييس التي تجيب عن سؤال التقييم.","احسب المؤشرات على عينات مناسبة وقارن الفئات.","حلل الحساسية واللايقين وقدم النتائج مع سياقها."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"مخططات موثوقية التنبؤ الاحتمالي","text":"فسر مخططاً تكون فيه فئة 70% قد تحققت في 50% من الحالات. استخدم مجموعة صغيرة افتراضية للتوضيح، ولا تعمم نتيجة عينة محدودة على الأداء المناخي الكامل."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر مخططاً تكون فيه فئة 70% قد تحققت في 50% من الحالات."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اختيار مقياس لا يلائم طبيعة الحدث أو توزيع العينة.","تسرب بيانات فترة التقييم إلى المعايرة أو التطوير.","إهمال جودة المرجع أو اختلاف التمثيل المكاني.","تفسير المؤشر دون معدل حدوث الظاهرة وحجم العينة.","اعتبار الارتباط أو التمييز دليلاً كافياً على المعايرة."]},{"type":"callout","text":"التحقق الجيد يربط المقياس بسؤال القرار، ويعرض خصائص العينة وعدم اليقين وحدود المقارنة بوضوح."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يحول التحقق أرشيف التوقعات والمشاهدات إلى دليل قابل للمقارنة والتحسين. وتحتاج الممارسة المهنية إلى مقاييس متعددة ومرجع موثوق وفصل مستقل بين التطوير والتقييم."}]}'::jsonb,9020,55,'["شرح مبدأ مقياس التحقق أو إطار التقييم","اختيار البيانات والعينة والمرجع المناسب","تفسير نتائج المهارة واللايقين لأغراض التحسين التشغيلي"]'::jsonb,'مقاييس التحقق الحتمي والأحداث'),
